-- UTF-8. Generated by order_actor_repair.py generate; fixed reviewed tenant-1 manifest.
-- Requires V311 in both ledgers. Apply via fail-fast client; never --force.
-- DDL may commit independently. Data, evidence, postconditions and both ledgers share one transaction.
-- Empty targets seed no business rows; existing mismatched targets reject the whole batch.
-- Initial actor checks exclude unrelated snapshot bytes changed by V305/V309.
-- Before/after images are immutable. Replay is zero-write; later edits reject recovery.
-- Rollback requires reviewed after-image guards; keep the additive nullable column.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP PROCEDURE IF EXISTS zsjos_v312_apply;
DELIMITER $$
CREATE PROCEDURE zsjos_v312_apply()
body: BEGIN
 DECLARE lock_ok INT DEFAULT 0;
 DECLARE repair_time DATETIME(6);
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  ROLLBACK;
  DO RELEASE_LOCK(CONCAT('v312:',DATABASE()));
  RESIGNAL;
 END;
 SELECT GET_LOCK(CONCAT('v312:',DATABASE()),10) INTO lock_ok;
 IF COALESCE(lock_ok,0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 lock unavailable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V311') OR
    NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V311') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 requires V311';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE()
     AND table_name='zsjos_order' AND column_name='repaired_actor_snapshot') THEN
  ALTER TABLE zsjos_order ADD COLUMN repaired_actor_snapshot JSON NULL COMMENT '经确认补录或修正的订单人员快照';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE()
     AND table_name='zsjos_order' AND column_name='repaired_actor_snapshot' AND data_type='json' AND is_nullable='YES') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 incompatible snapshot column';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE()
     AND table_name='zsjos_data_repair_backup' AND column_name='old_value' AND data_type='longtext') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 requires LONGTEXT evidence';
 END IF;
 DROP TEMPORARY TABLE IF EXISTS v312_manifest;
 CREATE TEMPORARY TABLE v312_manifest(
  order_no VARCHAR(64) PRIMARY KEY, status_value VARCHAR(32), old_submitter BIGINT, old_formal BIGINT,
  target BIGINT, formal_target BIGINT, round_no INT, old_round_submitter BIGINT,
  round_key VARCHAR(100), has_bpm BOOLEAN, snapshot_sha CHAR(64), imported_sha CHAR(64),
  name_sha CHAR(64), repair_round BOOLEAN, repair_actor BOOLEAN, repair_formal BOOLEAN
 ) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
