 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
 START TRANSACTION;
 SET repair_time=NOW();
IF EXISTS(SELECT 1 FROM v312_manifest m JOIN zsjos_order o ON o.order_no=m.order_no AND o.tenant_id=1 WHERE o.deleted<>0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 target deleted'; END IF;
IF EXISTS(SELECT 1 FROM v312_manifest m JOIN zsjos_order o ON o.order_no=m.order_no AND o.tenant_id=1 GROUP BY m.order_no HAVING COUNT(*)<>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 duplicate order'; END IF;
IF EXISTS(SELECT 1 FROM v312_manifest m JOIN zsjos_order o ON o.order_no=m.order_no AND o.tenant_id=1 LEFT JOIN system_users u ON u.id=m.target AND u.tenant_id=1 WHERE u.id IS NULL OR u.deleted<>0 OR u.status<>0 OR SHA2(u.nickname,256)<>m.name_sha) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 account changed'; END IF;
IF EXISTS(SELECT 1 FROM v312_manifest m JOIN zsjos_order o ON o.order_no=m.order_no AND o.tenant_id=1 LEFT JOIN zsjos_order_approval_round r ON r.id=o.current_approval_round_id AND r.order_id=o.id AND r.tenant_id=1 AND r.deleted=0 WHERE NOT(o.status <=> m.status_value) OR NOT(r.round_no <=> m.round_no) OR NOT(r.process_definition_key <=> m.round_key) OR NOT((r.process_instance_id IS NOT NULL AND r.process_instance_id<>'') <=> m.has_bpm) OR (r.id IS NOT NULL AND EXISTS(SELECT 1 FROM zsjos_order_approval_round z WHERE z.order_id=o.id AND z.tenant_id=1 AND z.deleted=0 AND z.round_no>r.round_no))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 order or round changed'; END IF;
IF EXISTS(SELECT 1 FROM v312_manifest m JOIN zsjos_order o ON o.order_no=m.order_no AND o.tenant_id=1 LEFT JOIN zsjos_order_approval_round r ON r.id=o.current_approval_round_id AND r.tenant_id=1 WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND b.table_name='zsjos_order' AND b.row_id=o.id) AND (NOT(o.submitter_user_id <=> m.old_submitter) OR NOT(o.formal_sales_user_id <=> m.old_formal) OR NOT(SHA2(CAST(o.imported_actor_snapshot AS CHAR),256) <=> m.imported_sha) OR o.repaired_actor_snapshot IS NOT NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 order preimage changed'; END IF;
IF EXISTS(SELECT 1 FROM v312_manifest m JOIN zsjos_order o ON o.order_no=m.order_no AND o.tenant_id=1 JOIN zsjos_order_approval_round r ON r.id=o.current_approval_round_id AND r.tenant_id=1 WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND b.table_name='zsjos_order_approval_round' AND b.row_id=r.id) AND (NOT(r.submitted_by_user_id <=> m.old_round_submitter))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 round preimage changed'; END IF;
 DROP TEMPORARY TABLE IF EXISTS v312_images;
 CREATE TEMPORARY TABLE v312_images(table_name VARCHAR(64),row_id BIGINT,current_image JSON,before_image JSON,after_image JSON,PRIMARY KEY(table_name,row_id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT INTO v312_images(table_name,row_id,current_image) SELECT 'zsjos_order',o.id,JSON_OBJECT('id',o.`id`,'order_no',o.`order_no`,'lead_id',o.`lead_id`,'source_payment_order_id',o.`source_payment_order_id`,'purchase_intent_id',o.`purchase_intent_id`,'opportunity_id',o.`opportunity_id`,'person_id',o.`person_id`,'order_type',o.`order_type`,'status',o.`status`,'submitter_user_id',o.`submitter_user_id`,'formal_sales_user_id',o.`formal_sales_user_id`,'submitter_center_type',o.`submitter_center_type`,'buyer_name',o.`buyer_name`,'student_name',o.`student_name`,'student_nature',o.`student_nature`,'student_mobile',o.`student_mobile`,'student_wechat_id',o.`student_wechat_id`,'province_code',o.`province_code`,'province_name',o.`province_name`,'city_code',o.`city_code`,'city_name',o.`city_name`,'agreed_exam_time',o.`agreed_exam_time`,'class_type',o.`class_type`,'service_period',o.`service_period`,'student_source',o.`student_source`,'total_amount',o.`total_amount`,'discount_amount',o.`discount_amount`,'payable_amount',o.`payable_amount`,'customer_paid_at',DATE_FORMAT(o.`customer_paid_at`,'%Y-%m-%d %H:%i:%s.%f'),'fee_mode',o.`fee_mode`,'payment_method',o.`payment_method`,'remark',o.`remark`,'student_special_requirements',o.`student_special_requirements`,'material_delivery_contact',o.`material_delivery_contact`,'gift_items',o.`gift_items`,'gift_shipping_address',o.`gift_shipping_address`,'payment_voucher_refs',o.`payment_voucher_refs`,'submission_idempotency_key',o.`submission_idempotency_key`,'submission_request_fingerprint',o.`submission_request_fingerprint`,'repurchase_reason',o.`repurchase_reason`,'termination_reason',o.`termination_reason`,'terminated_at',DATE_FORMAT(o.`terminated_at`,'%Y-%m-%d %H:%i:%s.%f'),'contract_refs',o.`contract_refs`,'current_approval_round_id',o.`current_approval_round_id`,'supersedes_order_id',o.`supersedes_order_id`,'superseded_by_order_id',o.`superseded_by_order_id`,'submitted_at',DATE_FORMAT(o.`submitted_at`,'%Y-%m-%d %H:%i:%s.%f'),'effective_at',DATE_FORMAT(o.`effective_at`,'%Y-%m-%d %H:%i:%s.%f'),'cancelled_at',DATE_FORMAT(o.`cancelled_at`,'%Y-%m-%d %H:%i:%s.%f'),'cancel_reason',o.`cancel_reason`,'zero_amount_reason',o.`zero_amount_reason`,'zero_amount_approved_by_user_id',o.`zero_amount_approved_by_user_id`,'version',o.`version`,'creator',o.`creator`,'create_time',DATE_FORMAT(o.`create_time`,'%Y-%m-%d %H:%i:%s.%f'),'updater',o.`updater`,'update_time',DATE_FORMAT(o.`update_time`,'%Y-%m-%d %H:%i:%s.%f'),'deleted',CAST(o.`deleted` AS UNSIGNED),'tenant_id',o.`tenant_id`,'active_lead_id',o.`active_lead_id`,'active_repurchase_person_id',o.`active_repurchase_person_id`,'formal_owner_identity',o.`formal_owner_identity`,'imported_actor_snapshot',o.`imported_actor_snapshot`,'fee_mode_label_snapshot',o.`fee_mode_label_snapshot`,'payment_method_label_snapshot',o.`payment_method_label_snapshot`,'repaired_actor_snapshot',o.`repaired_actor_snapshot`) FROM zsjos_order o JOIN v312_manifest m ON m.order_no=o.order_no WHERE o.tenant_id=1 AND o.deleted=0;
INSERT INTO v312_images(table_name,row_id,current_image) SELECT 'zsjos_order_approval_round',r.id,JSON_OBJECT('id',r.`id`,'order_id',r.`order_id`,'round_no',r.`round_no`,'status',r.`status`,'order_snapshot',r.`order_snapshot`,'process_instance_id',r.`process_instance_id`,'process_definition_key',r.`process_definition_key`,'submitted_by_user_id',r.`submitted_by_user_id`,'submitted_at',DATE_FORMAT(r.`submitted_at`,'%Y-%m-%d %H:%i:%s.%f'),'completed_at',DATE_FORMAT(r.`completed_at`,'%Y-%m-%d %H:%i:%s.%f'),'rejected_bpm_task_id',r.`rejected_bpm_task_id`,'decision_reason',r.`decision_reason`,'submission_idempotency_key',r.`submission_idempotency_key`,'registration_decision_idempotency_key',r.`registration_decision_idempotency_key`,'finance_decision_idempotency_key',r.`finance_decision_idempotency_key`,'termination_idempotency_key',r.`termination_idempotency_key`,'supervisor_confirmation_enabled',CAST(r.`supervisor_confirmation_enabled` AS UNSIGNED),'version',r.`version`,'creator',r.`creator`,'create_time',DATE_FORMAT(r.`create_time`,'%Y-%m-%d %H:%i:%s.%f'),'updater',r.`updater`,'update_time',DATE_FORMAT(r.`update_time`,'%Y-%m-%d %H:%i:%s.%f'),'deleted',CAST(r.`deleted` AS UNSIGNED),'tenant_id',r.`tenant_id`) FROM zsjos_order o JOIN v312_manifest m ON m.order_no=o.order_no JOIN zsjos_order_approval_round r ON r.id=o.current_approval_round_id AND r.order_id=o.id AND r.tenant_id=1 AND r.deleted=0 WHERE o.tenant_id=1 AND o.deleted=0;
INSERT INTO v312_images(table_name,row_id,current_image) SELECT 'zsjos_performance_attribution',a.id,JSON_OBJECT('id',a.`id`,'outcome',a.`outcome`,'completed_at',DATE_FORMAT(a.`completed_at`,'%Y-%m-%d %H:%i:%s.%f'),'fact_type',a.`fact_type`,'fact_id',a.`fact_id`,'user_id',a.`user_id`,'user_name',a.`user_name`,'dept_id',a.`dept_id`,'dept_name',a.`dept_name`,'center_id',a.`center_id`,'center_name',a.`center_name`,'lead_id',a.`lead_id`,'assignment_id',a.`assignment_id`,'received_at',DATE_FORMAT(a.`received_at`,'%Y-%m-%d %H:%i:%s.%f'),'source_group',a.`source_group`,'channel_code',a.`channel_code`,'channel_label',a.`channel_label`,'creator',a.`creator`,'create_time',DATE_FORMAT(a.`create_time`,'%Y-%m-%d %H:%i:%s.%f'),'updater',a.`updater`,'update_time',DATE_FORMAT(a.`update_time`,'%Y-%m-%d %H:%i:%s.%f'),'deleted',CAST(a.`deleted` AS UNSIGNED),'tenant_id',a.`tenant_id`,'org_source',a.`org_source`) FROM zsjos_performance_attribution a JOIN zsjos_order o ON o.id=a.fact_id AND o.tenant_id=a.tenant_id WHERE o.order_no='OR202609160008' AND o.tenant_id=1 AND o.deleted=0 AND a.fact_type='ORDER' AND a.deleted=0;
IF EXISTS(SELECT 1 FROM zsjos_order WHERE tenant_id=1 AND deleted=0 AND order_no='OR202609160008') AND (SELECT COUNT(*) FROM v312_images WHERE table_name='zsjos_performance_attribution')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 attribution missing or duplicated'; END IF;
IF EXISTS(SELECT 1 FROM v312_images i WHERE table_name='zsjos_performance_attribution' AND NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND b.table_name=i.table_name AND b.row_id=i.row_id) AND (NOT(i.current_image->>'$.user_id' <=> '37') OR NOT(i.current_image->>'$.dept_id' <=> '1051') OR NOT(i.current_image->>'$.org_source' <=> 'current') OR i.current_image->>'$.assignment_id'<>'null')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 attribution preimage changed'; END IF;
 UPDATE v312_images SET before_image=current_image,after_image=current_image;
 UPDATE v312_images i JOIN zsjos_order o ON i.table_name='zsjos_order' AND i.row_id=o.id
 JOIN v312_manifest m ON m.order_no=o.order_no JOIN system_users u ON u.id=m.target AND u.tenant_id=1
 SET i.after_image=JSON_SET(i.current_image,'$.submitter_user_id',m.target,'$.formal_sales_user_id',m.formal_target);
 UPDATE v312_images i JOIN zsjos_order o ON i.table_name='zsjos_order' AND i.row_id=o.id
 JOIN v312_manifest m ON m.order_no=o.order_no JOIN system_users u ON u.id=m.target AND u.tenant_id=1
 SET i.after_image=JSON_SET(i.after_image,'$.repaired_actor_snapshot',JSON_OBJECT(
  'version',1,'tenantId',1,'orderNo',o.order_no,'repairKey','order-actors-v312',
  'capturedAt',DATE_FORMAT(repair_time,'%Y-%m-%dT%H:%i:%s.%f+08:00'),
  'submitter',JSON_OBJECT('subjectType','ADMIN','id',m.target,'name',u.nickname,'identity',o.submitter_center_type)))
 WHERE m.repair_actor=1;
 UPDATE v312_images i JOIN zsjos_order o ON i.table_name='zsjos_order' AND i.row_id=o.id
 JOIN v312_manifest m ON m.order_no=o.order_no JOIN system_users u ON u.id=m.formal_target AND u.tenant_id=1
 SET i.after_image=JSON_SET(i.after_image,'$.repaired_actor_snapshot.formalSales',
  JSON_OBJECT('subjectType','ADMIN','id',m.formal_target,'name',u.nickname,'identity',o.formal_owner_identity))
 WHERE m.repair_formal=1;
 UPDATE v312_images i JOIN zsjos_order o ON i.table_name='zsjos_order' AND i.row_id=o.id
 JOIN v312_manifest m ON m.order_no=o.order_no
 SET i.after_image=JSON_SET(i.after_image,'$.imported_actor_snapshot.submitter.orderUserId',m.target)
 WHERE JSON_TYPE(o.imported_actor_snapshot->'$.submitter')='OBJECT' AND m.repair_actor=1;
 UPDATE v312_images i JOIN zsjos_order o ON i.table_name='zsjos_order' AND i.row_id=o.id
 JOIN v312_manifest m ON m.order_no=o.order_no
 SET i.after_image=JSON_SET(i.after_image,'$.imported_actor_snapshot.formalSales.orderUserId',m.formal_target)
 WHERE JSON_TYPE(o.imported_actor_snapshot->'$.formalSales')='OBJECT' AND m.repair_formal=1;
 UPDATE v312_images i JOIN zsjos_order_approval_round r ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id
 JOIN zsjos_order o ON o.id=r.order_id AND o.tenant_id=1 JOIN v312_manifest m ON m.order_no=o.order_no
 SET i.after_image=JSON_SET(i.after_image,'$.submitted_by_user_id',m.target) WHERE m.repair_round=1;
 UPDATE v312_images i JOIN zsjos_order_approval_round r ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id
 JOIN zsjos_order o ON o.id=r.order_id AND o.tenant_id=1 JOIN v312_manifest m ON m.order_no=o.order_no
 JOIN system_users u ON u.id=m.target AND u.tenant_id=1
 SET i.after_image=JSON_SET(i.after_image,'$.order_snapshot',JSON_SET(r.order_snapshot,
  '$.submitter',JSON_OBJECT('subjectType','ADMIN','id',m.target,'name',u.nickname,'identity',o.submitter_center_type)))
 WHERE m.repair_actor=1;
 UPDATE v312_images i JOIN zsjos_order_approval_round r ON i.table_name='zsjos_order_approval_round' AND i.row_id=r.id
 JOIN zsjos_order o ON o.id=r.order_id AND o.tenant_id=1 JOIN v312_manifest m ON m.order_no=o.order_no
 JOIN system_users u ON u.id=m.formal_target AND u.tenant_id=1
 SET i.after_image=JSON_SET(i.after_image,'$.order_snapshot',JSON_SET(i.after_image->'$.order_snapshot',
  '$.formalSales',JSON_OBJECT('subjectType','ADMIN','id',m.formal_target,'name',u.nickname,'identity',o.formal_owner_identity)))
 WHERE m.repair_formal=1;
IF EXISTS(SELECT 1 FROM v312_images WHERE table_name='zsjos_performance_attribution') AND (NOT EXISTS(SELECT 1 FROM system_users u JOIN system_dept d ON d.id=u.dept_id AND d.tenant_id=1 AND d.deleted=0 WHERE u.id=30 AND u.tenant_id=1 AND u.dept_id=1051 AND u.deleted=0 AND u.status=0) OR EXISTS(SELECT 1 FROM zsjos_performance_org WHERE tenant_id=1 AND deleted=0 AND dept_id=1051)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 attribution organization changed'; END IF;
 UPDATE v312_images i JOIN system_users u ON u.id=30 AND u.tenant_id=1
 JOIN system_dept d ON d.id=u.dept_id AND d.tenant_id=1
 SET i.after_image=JSON_SET(i.after_image,'$.user_id',30,'$.user_name',u.nickname,
  '$.dept_id',u.dept_id,'$.dept_name',d.name,'$.center_id',NULL,'$.center_name',NULL)
 WHERE i.table_name='zsjos_performance_attribution';
 UPDATE v312_images SET after_image=JSON_SET(after_image,'$.updater','order-actors-v312',
  '$.update_time',DATE_FORMAT(repair_time,'%Y-%m-%d %H:%i:%s.%f')) WHERE NOT(current_image=after_image);
 UPDATE v312_images SET after_image=JSON_SET(after_image,'$.version',CAST(current_image->>'$.version' AS UNSIGNED)+1)
 WHERE table_name IN ('zsjos_order','zsjos_order_approval_round') AND NOT(current_image=after_image);
IF EXISTS(SELECT 1 FROM v312_images i WHERE (SELECT COUNT(*) FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND b.table_name=i.table_name AND b.row_id=i.row_id) NOT IN (0,2)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 incomplete evidence'; END IF;
IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND (b.column_name NOT IN ('__before__','__after__') OR NOT EXISTS(SELECT 1 FROM v312_images i WHERE i.table_name=b.table_name AND i.row_id=b.row_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 orphan evidence'; END IF;
 UPDATE v312_images i JOIN zsjos_data_repair_backup b ON b.repair_key='order-actors-v312'
 AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__' SET i.before_image=CAST(b.old_value AS JSON);
 UPDATE v312_images i JOIN zsjos_data_repair_backup b ON b.repair_key='order-actors-v312'
 AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__after__' SET i.after_image=CAST(b.old_value AS JSON);
IF EXISTS(SELECT 1 FROM v312_images WHERE NOT(current_image=before_image OR current_image=after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 before/after conflict'; END IF;
INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'order-actors-v312',i.table_name,i.row_id,'__before__',CAST(i.before_image AS CHAR CHARACTER SET utf8mb4) FROM v312_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__before__');
INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'order-actors-v312',i.table_name,i.row_id,'__after__',CAST(i.after_image AS CHAR CHARACTER SET utf8mb4) FROM v312_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='order-actors-v312' AND b.table_name=i.table_name AND b.row_id=i.row_id AND b.column_name='__after__');
UPDATE zsjos_order a JOIN v312_images i ON i.table_name='zsjos_order' AND i.row_id=a.id SET a.`submitter_user_id`=NULLIF(i.after_image->>'$.submitter_user_id','null'),a.`formal_sales_user_id`=NULLIF(i.after_image->>'$.formal_sales_user_id','null'),a.`imported_actor_snapshot`=IF(JSON_TYPE(i.after_image->'$.imported_actor_snapshot')='NULL',NULL,i.after_image->'$.imported_actor_snapshot'),a.`repaired_actor_snapshot`=IF(JSON_TYPE(i.after_image->'$.repaired_actor_snapshot')='NULL',NULL,i.after_image->'$.repaired_actor_snapshot'),a.`version`=NULLIF(i.after_image->>'$.version','null'),a.`updater`=NULLIF(i.after_image->>'$.updater','null'),a.`update_time`=NULLIF(i.after_image->>'$.update_time','null') WHERE NOT(i.current_image=i.after_image);
IF EXISTS(SELECT 1 FROM zsjos_order a JOIN v312_images i ON i.table_name='zsjos_order' AND i.row_id=a.id WHERE NOT(JSON_OBJECT('id',a.`id`,'order_no',a.`order_no`,'lead_id',a.`lead_id`,'source_payment_order_id',a.`source_payment_order_id`,'purchase_intent_id',a.`purchase_intent_id`,'opportunity_id',a.`opportunity_id`,'person_id',a.`person_id`,'order_type',a.`order_type`,'status',a.`status`,'submitter_user_id',a.`submitter_user_id`,'formal_sales_user_id',a.`formal_sales_user_id`,'submitter_center_type',a.`submitter_center_type`,'buyer_name',a.`buyer_name`,'student_name',a.`student_name`,'student_nature',a.`student_nature`,'student_mobile',a.`student_mobile`,'student_wechat_id',a.`student_wechat_id`,'province_code',a.`province_code`,'province_name',a.`province_name`,'city_code',a.`city_code`,'city_name',a.`city_name`,'agreed_exam_time',a.`agreed_exam_time`,'class_type',a.`class_type`,'service_period',a.`service_period`,'student_source',a.`student_source`,'total_amount',a.`total_amount`,'discount_amount',a.`discount_amount`,'payable_amount',a.`payable_amount`,'customer_paid_at',DATE_FORMAT(a.`customer_paid_at`,'%Y-%m-%d %H:%i:%s.%f'),'fee_mode',a.`fee_mode`,'payment_method',a.`payment_method`,'remark',a.`remark`,'student_special_requirements',a.`student_special_requirements`,'material_delivery_contact',a.`material_delivery_contact`,'gift_items',a.`gift_items`,'gift_shipping_address',a.`gift_shipping_address`,'payment_voucher_refs',a.`payment_voucher_refs`,'submission_idempotency_key',a.`submission_idempotency_key`,'submission_request_fingerprint',a.`submission_request_fingerprint`,'repurchase_reason',a.`repurchase_reason`,'termination_reason',a.`termination_reason`,'terminated_at',DATE_FORMAT(a.`terminated_at`,'%Y-%m-%d %H:%i:%s.%f'),'contract_refs',a.`contract_refs`,'current_approval_round_id',a.`current_approval_round_id`,'supersedes_order_id',a.`supersedes_order_id`,'superseded_by_order_id',a.`superseded_by_order_id`,'submitted_at',DATE_FORMAT(a.`submitted_at`,'%Y-%m-%d %H:%i:%s.%f'),'effective_at',DATE_FORMAT(a.`effective_at`,'%Y-%m-%d %H:%i:%s.%f'),'cancelled_at',DATE_FORMAT(a.`cancelled_at`,'%Y-%m-%d %H:%i:%s.%f'),'cancel_reason',a.`cancel_reason`,'zero_amount_reason',a.`zero_amount_reason`,'zero_amount_approved_by_user_id',a.`zero_amount_approved_by_user_id`,'version',a.`version`,'creator',a.`creator`,'create_time',DATE_FORMAT(a.`create_time`,'%Y-%m-%d %H:%i:%s.%f'),'updater',a.`updater`,'update_time',DATE_FORMAT(a.`update_time`,'%Y-%m-%d %H:%i:%s.%f'),'deleted',CAST(a.`deleted` AS UNSIGNED),'tenant_id',a.`tenant_id`,'active_lead_id',a.`active_lead_id`,'active_repurchase_person_id',a.`active_repurchase_person_id`,'formal_owner_identity',a.`formal_owner_identity`,'imported_actor_snapshot',a.`imported_actor_snapshot`,'fee_mode_label_snapshot',a.`fee_mode_label_snapshot`,'payment_method_label_snapshot',a.`payment_method_label_snapshot`,'repaired_actor_snapshot',a.`repaired_actor_snapshot`)=i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 postcondition zsjos_order'; END IF;
UPDATE zsjos_order_approval_round a JOIN v312_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=a.id SET a.`submitted_by_user_id`=NULLIF(i.after_image->>'$.submitted_by_user_id','null'),a.`order_snapshot`=IF(JSON_TYPE(i.after_image->'$.order_snapshot')='NULL',NULL,i.after_image->'$.order_snapshot'),a.`version`=NULLIF(i.after_image->>'$.version','null'),a.`updater`=NULLIF(i.after_image->>'$.updater','null'),a.`update_time`=NULLIF(i.after_image->>'$.update_time','null') WHERE NOT(i.current_image=i.after_image);
IF EXISTS(SELECT 1 FROM zsjos_order_approval_round a JOIN v312_images i ON i.table_name='zsjos_order_approval_round' AND i.row_id=a.id WHERE NOT(JSON_OBJECT('id',a.`id`,'order_id',a.`order_id`,'round_no',a.`round_no`,'status',a.`status`,'order_snapshot',a.`order_snapshot`,'process_instance_id',a.`process_instance_id`,'process_definition_key',a.`process_definition_key`,'submitted_by_user_id',a.`submitted_by_user_id`,'submitted_at',DATE_FORMAT(a.`submitted_at`,'%Y-%m-%d %H:%i:%s.%f'),'completed_at',DATE_FORMAT(a.`completed_at`,'%Y-%m-%d %H:%i:%s.%f'),'rejected_bpm_task_id',a.`rejected_bpm_task_id`,'decision_reason',a.`decision_reason`,'submission_idempotency_key',a.`submission_idempotency_key`,'registration_decision_idempotency_key',a.`registration_decision_idempotency_key`,'finance_decision_idempotency_key',a.`finance_decision_idempotency_key`,'termination_idempotency_key',a.`termination_idempotency_key`,'supervisor_confirmation_enabled',CAST(a.`supervisor_confirmation_enabled` AS UNSIGNED),'version',a.`version`,'creator',a.`creator`,'create_time',DATE_FORMAT(a.`create_time`,'%Y-%m-%d %H:%i:%s.%f'),'updater',a.`updater`,'update_time',DATE_FORMAT(a.`update_time`,'%Y-%m-%d %H:%i:%s.%f'),'deleted',CAST(a.`deleted` AS UNSIGNED),'tenant_id',a.`tenant_id`)=i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 postcondition zsjos_order_approval_round'; END IF;
UPDATE zsjos_performance_attribution a JOIN v312_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=a.id SET a.`user_id`=NULLIF(i.after_image->>'$.user_id','null'),a.`user_name`=NULLIF(i.after_image->>'$.user_name','null'),a.`dept_id`=NULLIF(i.after_image->>'$.dept_id','null'),a.`dept_name`=NULLIF(i.after_image->>'$.dept_name','null'),a.`center_id`=NULLIF(i.after_image->>'$.center_id','null'),a.`center_name`=NULLIF(i.after_image->>'$.center_name','null'),a.`updater`=NULLIF(i.after_image->>'$.updater','null'),a.`update_time`=NULLIF(i.after_image->>'$.update_time','null') WHERE NOT(i.current_image=i.after_image);
IF EXISTS(SELECT 1 FROM zsjos_performance_attribution a JOIN v312_images i ON i.table_name='zsjos_performance_attribution' AND i.row_id=a.id WHERE NOT(JSON_OBJECT('id',a.`id`,'outcome',a.`outcome`,'completed_at',DATE_FORMAT(a.`completed_at`,'%Y-%m-%d %H:%i:%s.%f'),'fact_type',a.`fact_type`,'fact_id',a.`fact_id`,'user_id',a.`user_id`,'user_name',a.`user_name`,'dept_id',a.`dept_id`,'dept_name',a.`dept_name`,'center_id',a.`center_id`,'center_name',a.`center_name`,'lead_id',a.`lead_id`,'assignment_id',a.`assignment_id`,'received_at',DATE_FORMAT(a.`received_at`,'%Y-%m-%d %H:%i:%s.%f'),'source_group',a.`source_group`,'channel_code',a.`channel_code`,'channel_label',a.`channel_label`,'creator',a.`creator`,'create_time',DATE_FORMAT(a.`create_time`,'%Y-%m-%d %H:%i:%s.%f'),'updater',a.`updater`,'update_time',DATE_FORMAT(a.`update_time`,'%Y-%m-%d %H:%i:%s.%f'),'deleted',CAST(a.`deleted` AS UNSIGNED),'tenant_id',a.`tenant_id`,'org_source',a.`org_source`)=i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V312 postcondition zsjos_performance_attribution'; END IF;
 INSERT INTO zsjos_schema_version(version,description,checksum)
 SELECT 'V312','Reviewed order actors and snapshots',SHA2('V312__order_actor_snapshot_repair.sql',256)
 WHERE NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V312');
 INSERT INTO zsjos_module_schema_version(module_code,version,description,checksum,release_version)
 SELECT 'core','V312','Reviewed order actors and snapshots',SHA2('V312__order_actor_snapshot_repair.sql',256),'baseline'
 WHERE NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V312');
 COMMIT;
 DO RELEASE_LOCK(CONCAT('v312:',DATABASE()));
END$$
DELIMITER ;
CALL zsjos_v312_apply();
DROP PROCEDURE zsjos_v312_apply;
